-- Phase 5.8 tenant-scoped CRM customer profiles, live segments and timelines.
create or replace function public.get_restaurant_customer_crm_metrics(p_restaurant_id uuid,p_customer_user_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_result jsonb;v_email text;
begin
 if not public.is_restaurant_member(p_restaurant_id) and not public.is_platform_admin() then raise exception 'Restaurant access denied' using errcode='42501';end if;
 select email into v_email from auth.users where id=p_customer_user_id;
 with paid_orders as(select * from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id and payment_status='paid' and order_status<>'rejected'),
 order_stats as(select min(created_at) first_order_date,max(created_at) last_order_date,coalesce(sum(total_pence),0)::bigint lifetime_spend_pence,count(*)::integer total_orders from paid_orders),
 favourite_items as(select coalesce(jsonb_agg(jsonb_build_object('id',x.menu_item_id,'name',x.item_name,'quantity',x.qty) order by x.qty desc),'[]'::jsonb) value from(select oi.menu_item_id,max(oi.item_name) item_name,sum(oi.quantity)::integer qty from paid_orders po join public.order_items oi on oi.order_id=po.id group by oi.menu_item_id order by sum(oi.quantity) desc limit 5)x),
 favourite_categories as(select coalesce(jsonb_agg(jsonb_build_object('id',x.category_id,'name',x.category_name,'quantity',x.qty) order by x.qty desc),'[]'::jsonb) value from(select mc.id category_id,mc.name category_name,sum(oi.quantity)::integer qty from paid_orders po join public.order_items oi on oi.order_id=po.id join public.menu_items mi on mi.id=oi.menu_item_id join public.menu_categories mc on mc.id=mi.category_id group by mc.id,mc.name order by sum(oi.quantity) desc limit 5)x),
 referral_stats as(select count(*) filter(where status in('qualified','rewarded'))::integer qualified_referrals,count(*)::integer total_referrals from public.customer_referrals where restaurant_id=p_restaurant_id and referrer_user_id=p_customer_user_id),
 gift_stats as(select coalesce(sum(remaining_value_pence) filter(where is_active and(expires_at is null or expires_at>now())),0)::bigint balance,count(*) filter(where is_active and remaining_value_pence>0)::integer cards from public.restaurant_gift_cards where restaurant_id=p_restaurant_id and lower(recipient_email)=lower(coalesce(v_email,'')))
 select jsonb_build_object(
 'customer_user_id',p_customer_user_id,'first_order_date',os.first_order_date,'last_order_date',os.last_order_date,'days_since_last_order',case when os.last_order_date is null then null else floor(extract(epoch from(now()-os.last_order_date))/86400)::integer end,
 'lifetime_spend_pence',os.lifetime_spend_pence,'total_orders',os.total_orders,'average_order_value_pence',case when os.total_orders=0 then 0 else round(os.lifetime_spend_pence::numeric/os.total_orders)::bigint end,
 'favourite_items',fi.value,'favourite_categories',fc.value,'loyalty_points',coalesce(la.points_balance,0),
 'stamp_cards',coalesce((select jsonb_agg(jsonb_build_object('program_id',sc.program_id,'current_stamps',sc.current_stamps,'lifetime_stamps',sc.lifetime_stamps,'completed_cycles',sc.completed_cycles,'is_active',sc.is_active)) from public.customer_stamp_cards sc where sc.restaurant_id=p_restaurant_id and sc.customer_user_id=p_customer_user_id),'[]'::jsonb),
 'vip_tier_id',vm.current_tier_id,'vip_tier',case when vt.id is null then null else jsonb_build_object('id',vt.id,'name',vt.name,'colour',vt.colour,'icon',vt.icon) end,
 'qualified_referrals',rs.qualified_referrals,'total_referrals',rs.total_referrals,'birthday',cp.date_of_birth,'birthday_month',extract(month from cp.date_of_birth)::integer,
 'milestones',coalesce((select jsonb_agg(jsonb_build_object('id',ri.id,'source_type',ri.source_type,'status',ri.status,'issued_at',ri.issued_at,'redeemed_at',ri.redeemed_at)) from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=p_customer_user_id and ri.source_type in('birthday','milestone')),'[]'::jsonb),
 'challenge_progress',coalesce((select jsonb_agg(jsonb_build_object('challenge_id',ccp.challenge_id,'status',ccp.status,'progress_percent',ccp.progress_percent,'completed_at',ccp.completed_at)) from public.customer_challenge_progress ccp where ccp.restaurant_id=p_restaurant_id and ccp.customer_user_id=p_customer_user_id),'[]'::jsonb),
 'has_challenge_progress',exists(select 1 from public.customer_challenge_progress ccp where ccp.restaurant_id=p_restaurant_id and ccp.customer_user_id=p_customer_user_id),
 'wallet_balance_pence',coalesce(ca.balance_pence,0)+gs.balance,'store_credit_pence',coalesce(ca.balance_pence,0),'gift_card_balance_pence',gs.balance,'gift_card_count',gs.cards,
 'reward_history',coalesce((select jsonb_agg(jsonb_build_object('id',ri.id,'source_type',ri.source_type,'reward_type',ri.reward_type,'reward_value',ri.reward_value,'status',ri.status,'issued_at',ri.issued_at,'expires_at',ri.expires_at,'redeemed_at',ri.redeemed_at) order by ri.created_at desc) from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=p_customer_user_id),'[]'::jsonb),
 'has_reward_available',exists(select 1 from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=p_customer_user_id and ri.status in('available','issued') and(ri.expires_at is null or ri.expires_at>now())),
 'has_abandoned_reward',exists(select 1 from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=p_customer_user_id and ri.status in('available','issued') and ri.created_at<now()-interval '14 days' and(ri.expires_at is null or ri.expires_at>now())),
 'has_one_stamp_remaining',exists(select 1 from public.customer_stamp_cards sc join public.restaurant_stamp_programs sp on sp.id=sc.program_id where sc.restaurant_id=p_restaurant_id and sc.customer_user_id=p_customer_user_id and sc.is_active and sp.is_active and sc.current_stamps=greatest(sp.stamps_required-1,0)),
 'marketing_preferences',jsonb_build_object('global',coalesce(to_jsonb(gp)-'customer_user_id'-'created_at'-'updated_at','{}'::jsonb),'restaurant',coalesce(to_jsonb(rp)-'restaurant_id'-'customer_user_id'-'created_at'-'updated_at','{}'::jsonb)),
 'notes',coalesce((select jsonb_agg(jsonb_build_object('id',n.id,'note',n.note,'created_by',n.created_by,'created_at',n.created_at,'updated_at',n.updated_at) order by n.created_at desc) from public.restaurant_customer_notes n where n.restaurant_id=p_restaurant_id and n.customer_user_id=p_customer_user_id),'[]'::jsonb)) into v_result
 from order_stats os cross join favourite_items fi cross join favourite_categories fc cross join referral_stats rs cross join gift_stats gs
 left join public.customer_profiles cp on cp.user_id=p_customer_user_id left join public.customer_loyalty_accounts la on la.restaurant_id=p_restaurant_id and la.customer_user_id=p_customer_user_id
 left join public.customer_credit_accounts ca on ca.restaurant_id=p_restaurant_id and ca.customer_user_id=p_customer_user_id left join public.customer_vip_memberships vm on vm.restaurant_id=p_restaurant_id and vm.customer_user_id=p_customer_user_id
 left join public.restaurant_vip_tiers vt on vt.id=vm.current_tier_id left join public.customer_marketing_preferences gp on gp.customer_user_id=p_customer_user_id left join public.customer_restaurant_marketing_preferences rp on rp.restaurant_id=p_restaurant_id and rp.customer_user_id=p_customer_user_id;
 return coalesce(v_result,'{}'::jsonb);
end $$;

create or replace function public.get_restaurant_crm_customers(p_restaurant_id uuid,p_segment_key text default null,p_custom_segment_id uuid default null,p_search text default null,p_limit integer default 100,p_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_limit integer:=least(greatest(coalesce(p_limit,100),1),250);v_offset integer:=greatest(coalesce(p_offset,0),0);v_filter jsonb:='{}';v_high integer;v_low integer;v_ref integer;v_result jsonb;
begin
 if not public.is_restaurant_member(p_restaurant_id) and not public.is_platform_admin() then raise exception 'Restaurant access denied' using errcode='42501';end if;
 select coalesce((select high_spender_pence from public.restaurant_marketing_settings where restaurant_id=p_restaurant_id),10000),coalesce((select low_spender_pence from public.restaurant_marketing_settings where restaurant_id=p_restaurant_id),3000),coalesce((select referral_champion_threshold from public.restaurant_marketing_settings where restaurant_id=p_restaurant_id),3) into v_high,v_low,v_ref;
 if p_custom_segment_id is not null then select filter_config into v_filter from public.restaurant_customer_segments where id=p_custom_segment_id and restaurant_id=p_restaurant_id and is_active;if not found then raise exception 'Segment not found';end if;end if;
 with base as(select o.customer_user_id,min(o.created_at) first_order_date,max(o.created_at) last_order_date,count(*)::integer total_orders,coalesce(sum(o.total_pence),0)::bigint lifetime_spend_pence from public.orders o where o.restaurant_id=p_restaurant_id and o.customer_user_id is not null and o.payment_status='paid' and o.order_status<>'rejected' group by o.customer_user_id),
 enriched as(select b.*,case when b.total_orders=0 then 0 else round(b.lifetime_spend_pence::numeric/b.total_orders)::bigint end average_order_value_pence,floor(extract(epoch from(now()-b.last_order_date))/86400)::integer days_since_last_order,cp.first_name,cp.last_name,cp.phone,cp.date_of_birth,u.email,coalesce(la.points_balance,0) loyalty_points,vm.current_tier_id vip_tier_id,vt.name vip_tier_name,vt.colour vip_tier_colour,vt.icon vip_tier_icon,coalesce(ca.balance_pence,0) store_credit_pence,
 (select count(*)::integer from public.customer_referrals r where r.restaurant_id=p_restaurant_id and r.referrer_user_id=b.customer_user_id and r.status in('qualified','rewarded')) qualified_referrals,
 exists(select 1 from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=b.customer_user_id and ri.status in('available','issued') and(ri.expires_at is null or ri.expires_at>now())) has_reward_available,
 exists(select 1 from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=b.customer_user_id and ri.status in('available','issued') and ri.created_at<now()-interval '14 days' and(ri.expires_at is null or ri.expires_at>now())) has_abandoned_reward,
 exists(select 1 from public.customer_stamp_cards sc join public.restaurant_stamp_programs sp on sp.id=sc.program_id where sc.restaurant_id=p_restaurant_id and sc.customer_user_id=b.customer_user_id and sc.is_active and sp.is_active and sc.current_stamps=greatest(sp.stamps_required-1,0)) has_one_stamp_remaining,
 exists(select 1 from public.customer_challenge_progress ccp where ccp.restaurant_id=p_restaurant_id and ccp.customer_user_id=b.customer_user_id) has_challenge_progress,
 coalesce(gp.global_opt_out,false) global_opt_out,coalesce(rp.restaurant_opt_out,false) restaurant_opt_out,
 coalesce(gp.marketing_emails,false) and coalesce(rp.marketing_emails,true) and not coalesce(gp.global_opt_out,false) and not coalesce(rp.restaurant_opt_out,false) marketing_email_allowed,
 coalesce(gp.promotional_notifications,false) and coalesce(rp.promotional_notifications,true) and not coalesce(gp.global_opt_out,false) and not coalesce(rp.restaurant_opt_out,false) promotional_notification_allowed
 from base b left join auth.users u on u.id=b.customer_user_id left join public.customer_profiles cp on cp.user_id=b.customer_user_id left join public.customer_loyalty_accounts la on la.restaurant_id=p_restaurant_id and la.customer_user_id=b.customer_user_id left join public.customer_credit_accounts ca on ca.restaurant_id=p_restaurant_id and ca.customer_user_id=b.customer_user_id left join public.customer_vip_memberships vm on vm.restaurant_id=p_restaurant_id and vm.customer_user_id=b.customer_user_id left join public.restaurant_vip_tiers vt on vt.id=vm.current_tier_id left join public.customer_marketing_preferences gp on gp.customer_user_id=b.customer_user_id left join public.customer_restaurant_marketing_preferences rp on rp.restaurant_id=p_restaurant_id and rp.customer_user_id=b.customer_user_id),
 filtered as(select e.*,jsonb_build_object('lifetime_spend_pence',e.lifetime_spend_pence,'total_orders',e.total_orders,'days_since_last_order',e.days_since_last_order,'vip_tier_id',e.vip_tier_id,'birthday_month',extract(month from e.date_of_birth)::integer,'has_reward_available',e.has_reward_available,'has_one_stamp_remaining',e.has_one_stamp_remaining,'has_challenge_progress',e.has_challenge_progress,'qualified_referrals',e.qualified_referrals) metrics from enriched e where p_search is null or btrim(p_search)='' or concat_ws(' ',e.first_name,e.last_name,e.email,e.phone) ilike '%'||btrim(p_search)||'%'),
 segmented as(select f.* from filtered f where(p_custom_segment_id is not null and public.marketing_segment_filter_matches(f.metrics,v_filter)) or(p_custom_segment_id is null and(p_segment_key is null or p_segment_key='' or p_segment_key='all' or(p_segment_key='new_customers' and f.total_orders=1 and f.first_order_date>=now()-interval '30 days') or(p_segment_key='returning_customers' and f.total_orders>=2) or(p_segment_key='vip_customers' and f.vip_tier_id is not null) or(p_segment_key='high_spenders' and f.lifetime_spend_pence>=v_high) or(p_segment_key='low_spenders' and f.lifetime_spend_pence<=v_low) or(p_segment_key='inactive_30_days' and f.days_since_last_order between 30 and 59) or(p_segment_key='inactive_60_days' and f.days_since_last_order between 60 and 89) or(p_segment_key='inactive_90_plus_days' and f.days_since_last_order>=90) or(p_segment_key='birthday_this_month' and extract(month from f.date_of_birth)=extract(month from current_date)) or(p_segment_key='reward_available' and f.has_reward_available) or(p_segment_key='one_stamp_remaining' and f.has_one_stamp_remaining) or(p_segment_key='referral_champions' and f.qualified_referrals>=v_ref) or(p_segment_key='challenge_participants' and f.has_challenge_progress) or(p_segment_key='abandoned_rewards' and f.has_abandoned_reward)))),
 counted as(select count(*)::integer total from segmented),page as(select * from segmented order by lifetime_spend_pence desc,last_order_date desc limit v_limit offset v_offset)
 select jsonb_build_object('total',(select total from counted),'customers',coalesce((select jsonb_agg(to_jsonb(p)-'metrics') from page p),'[]'::jsonb)) into v_result;return v_result;
end $$;

create or replace function public.get_restaurant_crm_segments(p_restaurant_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_result jsonb;begin if not public.is_restaurant_member(p_restaurant_id) and not public.is_platform_admin() then raise exception 'Restaurant access denied' using errcode='42501';end if;select jsonb_build_object('built_in',jsonb_build_array(jsonb_build_object('key','new_customers','name','New customers'),jsonb_build_object('key','returning_customers','name','Returning customers'),jsonb_build_object('key','vip_customers','name','VIP customers'),jsonb_build_object('key','high_spenders','name','High spenders'),jsonb_build_object('key','low_spenders','name','Low spenders'),jsonb_build_object('key','inactive_30_days','name','Inactive 30 days'),jsonb_build_object('key','inactive_60_days','name','Inactive 60 days'),jsonb_build_object('key','inactive_90_plus_days','name','Inactive 90+ days'),jsonb_build_object('key','birthday_this_month','name','Birthday this month'),jsonb_build_object('key','reward_available','name','Reward available'),jsonb_build_object('key','one_stamp_remaining','name','One stamp remaining'),jsonb_build_object('key','referral_champions','name','Referral champions'),jsonb_build_object('key','challenge_participants','name','Challenge participants'),jsonb_build_object('key','abandoned_rewards','name','Customers with abandoned rewards')),'custom',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'description',s.description,'filter_config',s.filter_config,'is_active',s.is_active,'created_at',s.created_at) order by s.created_at desc) from public.restaurant_customer_segments s where s.restaurant_id=p_restaurant_id),'[]'::jsonb)) into v_result;return v_result;end $$;

create or replace function public.get_restaurant_customer_timeline(p_restaurant_id uuid,p_customer_user_id uuid,p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_result jsonb;begin if not public.is_restaurant_member(p_restaurant_id) and not public.is_platform_admin() then raise exception 'Restaurant access denied' using errcode='42501';end if;with events as(select o.created_at event_at,'order'::text event_type,o.id source_id,jsonb_build_object('order_number',o.order_number,'status',o.order_status,'total_pence',o.total_pence) details from public.orders o where o.restaurant_id=p_restaurant_id and o.customer_user_id=p_customer_user_id union all select l.created_at,'loyalty',l.id,jsonb_build_object('points_delta',l.points_delta,'entry_type',l.entry_type,'note',l.note) from public.customer_loyalty_ledger l where l.restaurant_id=p_restaurant_id and l.customer_user_id=p_customer_user_id union all select c.created_at,'wallet',c.id,jsonb_build_object('amount_pence',c.amount_pence,'entry_type',c.entry_type,'note',c.note) from public.customer_credit_ledger c where c.restaurant_id=p_restaurant_id and c.customer_user_id=p_customer_user_id union all select s.created_at,'stamp',s.id,jsonb_build_object('stamps_delta',s.stamps_delta,'event_type',s.event_type,'program_id',s.program_id) from public.customer_stamp_events s where s.restaurant_id=p_restaurant_id and s.customer_user_id=p_customer_user_id union all select r.created_at,'referral',r.id,jsonb_build_object('status',r.status,'referred_user_id',r.referred_user_id,'qualified_at',r.qualified_at,'rewarded_at',r.rewarded_at) from public.customer_referrals r where r.restaurant_id=p_restaurant_id and r.referrer_user_id=p_customer_user_id union all select vh.created_at,'vip',vh.id,jsonb_build_object('from_tier_id',vh.from_tier_id,'to_tier_id',vh.to_tier_id,'change_type',vh.change_type,'reason',vh.reason) from public.customer_vip_tier_history vh where vh.restaurant_id=p_restaurant_id and vh.customer_user_id=p_customer_user_id union all select coalesce(ccp.completed_at,ccp.last_progress_at,ccp.created_at),'challenge',ccp.id,jsonb_build_object('challenge_id',ccp.challenge_id,'status',ccp.status,'progress_percent',ccp.progress_percent) from public.customer_challenge_progress ccp where ccp.restaurant_id=p_restaurant_id and ccp.customer_user_id=p_customer_user_id union all select ri.created_at,'reward',ri.id,jsonb_build_object('source_type',ri.source_type,'reward_type',ri.reward_type,'status',ri.status,'issued_at',ri.issued_at,'redeemed_at',ri.redeemed_at) from public.customer_reward_issuances ri where ri.restaurant_id=p_restaurant_id and ri.customer_user_id=p_customer_user_id union all select n.created_at,'notification',n.id,jsonb_build_object('notification_type',n.notification_type,'title',n.title,'read_at',n.read_at) from public.customer_notifications n where n.restaurant_id=p_restaurant_id and n.customer_user_id=p_customer_user_id union all select rn.created_at,'support_note',rn.id,jsonb_build_object('note',rn.note,'created_by',rn.created_by) from public.restaurant_customer_notes rn where rn.restaurant_id=p_restaurant_id and rn.customer_user_id=p_customer_user_id) select coalesce(jsonb_agg(jsonb_build_object('event_at',event_at,'event_type',event_type,'source_id',source_id,'details',details) order by event_at desc),'[]'::jsonb) into v_result from(select * from events order by event_at desc limit least(greatest(coalesce(p_limit,100),1),250))x;return v_result;end $$;
create or replace function public.get_restaurant_crm_customer_profile(p_restaurant_id uuid,p_customer_user_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_metrics jsonb;v_email text;v_profile jsonb;begin if not public.is_restaurant_member(p_restaurant_id) and not public.is_platform_admin() then raise exception 'Restaurant access denied' using errcode='42501';end if;if not exists(select 1 from public.orders where restaurant_id=p_restaurant_id and customer_user_id=p_customer_user_id) then raise exception 'Customer not found';end if;select email into v_email from auth.users where id=p_customer_user_id;v_metrics:=public.get_restaurant_customer_crm_metrics(p_restaurant_id,p_customer_user_id);select jsonb_build_object('customer_user_id',p_customer_user_id,'name',btrim(concat_ws(' ',cp.first_name,cp.last_name)),'first_name',cp.first_name,'last_name',cp.last_name,'email',v_email,'phone',cp.phone,'birthday',cp.date_of_birth) into v_profile from public.customer_profiles cp where cp.user_id=p_customer_user_id;if v_profile is null then v_profile:=jsonb_build_object('customer_user_id',p_customer_user_id,'email',v_email);end if;return v_profile||v_metrics||jsonb_build_object('timeline',public.get_restaurant_customer_timeline(p_restaurant_id,p_customer_user_id,100));end $$;
revoke all on function public.get_restaurant_customer_crm_metrics(uuid,uuid),public.get_restaurant_crm_customers(uuid,text,uuid,text,integer,integer),public.get_restaurant_crm_segments(uuid),public.get_restaurant_customer_timeline(uuid,uuid,integer),public.get_restaurant_crm_customer_profile(uuid,uuid) from public;
grant execute on function public.get_restaurant_customer_crm_metrics(uuid,uuid),public.get_restaurant_crm_customers(uuid,text,uuid,text,integer,integer),public.get_restaurant_crm_segments(uuid),public.get_restaurant_customer_timeline(uuid,uuid,integer),public.get_restaurant_crm_customer_profile(uuid,uuid) to authenticated;
